
-- Handbook v1.14 remediation: distinct ordinary correspondence with explicit handling context.
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'translated record' WHEN 1 THEN 'hospitalfollow-up appointmenttranslated record' WHEN 2 THEN 'translated record'
      WHEN 3 THEN 'translated recordexamtranslated record' WHEN 4 THEN 'translated record' WHEN 5 THEN 'translated record'
      WHEN 6 THEN 'translated record' WHEN 7 THEN 'translated record' WHEN 8 THEN 'stationeryordertranslated record'
      WHEN 9 THEN 'National Graduate Entrance Examinationtranslated record' WHEN 10 THEN 'translated recordnotice' WHEN 11 THEN 'rehabilitationtranslated record'
      WHEN 12 THEN 'translated record' WHEN 13 THEN 'translated record' WHEN 14 THEN 'translated record'
      WHEN 15 THEN 'translated record' ELSE 'examtranslated record' END AS mail_fact,
    CASE rowid % 19
      WHEN 0 THEN 'translated record' WHEN 1 THEN 'translated record' WHEN 2 THEN 'translated record' WHEN 3 THEN 'not purchase authorization'
      WHEN 4 THEN 'translated record' WHEN 5 THEN 'translated record' WHEN 6 THEN 'translated record' WHEN 7 THEN 'translated recordemail'
      WHEN 8 THEN 'translated record' WHEN 9 THEN 'follow the doctor official opinion' WHEN 10 THEN 'follow later exam authority notices' WHEN 11 THEN 'translated record'
      WHEN 12 THEN 'translated record' WHEN 13 THEN 'translated record' WHEN 14 THEN 'translated record' WHEN 15 THEN 'translated record'
      WHEN 16 THEN 'translated record' WHEN 17 THEN 'translated recordbudgettranslated record' ELSE 'translated record' END AS handling_fact
  FROM messages WHERE message_id LIKE 'msg_bg_%'
)
UPDATE messages
SET from_addr=CASE rowid % 17
      WHEN 0 THEN 'course.materials@learning-harbor.example'
      WHEN 1 THEN 'parking.office@riverside-clinic.example'
      WHEN 2 THEN 'dispatch@neighborhood-grocery.example'
      WHEN 3 THEN 'exam.rooms@north-library.example'
      WHEN 4 THEN 'study.group@campus-alumni.example'
      WHEN 5 THEN 'billing@family-utilities.example'
      WHEN 6 THEN 'assistant.wang@riverside-clinic.example'
      WHEN 7 THEN 'circulation@north-library.example'
      WHEN 8 THEN 'tracking@stationery-courier.example'
      WHEN 9 THEN 'replay@graduate-openclass.example'
      WHEN 10 THEN 'service@lakeside-property.example'
      WHEN 11 THEN 'care@rehab-supplies.example'
      WHEN 12 THEN 'weekly@study-platform.example'
      WHEN 13 THEN 'coordinator@community-volunteer.example'
      WHEN 14 THEN 'pickup@campus-print.example'
      WHEN 15 THEN 'statements@community-bank.example'
      ELSE 'digest@exam-information.example' END,
    subject=(SELECT mail_fact FROM facts WHERE facts.rid=messages.rowid),
    body_text=CASE rowid % 7
      WHEN 0 THEN (SELECT mail_fact || '。translated record：' || handling_fact || '。' FROM facts WHERE facts.rid=messages.rowid)
      WHEN 1 THEN (SELECT 'translated record：' || mail_fact || '；' || handling_fact || '。' FROM facts WHERE facts.rid=messages.rowid)
      WHEN 2 THEN (SELECT handling_fact || '。translated recordemailtranslated record“' || mail_fact || '”。' FROM facts WHERE facts.rid=messages.rowid)
      WHEN 3 THEN (SELECT 'translated recordemailtranslated record' || mail_fact || '，translated record' || handling_fact || '。' FROM facts WHERE facts.rid=messages.rowid)
      WHEN 4 THEN (SELECT 'translated record——' || mail_fact || '；translated record：' || handling_fact || '。' FROM facts WHERE facts.rid=messages.rowid)
      WHEN 5 THEN (SELECT mail_fact || 'translated record；' || handling_fact || '。' FROM facts WHERE facts.rid=messages.rowid)
      ELSE (SELECT 'translated record' || mail_fact || '。translated record' || handling_fact || '。' FROM facts WHERE facts.rid=messages.rowid)
    END,
    message_id=replace(message_id,'msg_bg_','msg_context_')
WHERE message_id LIKE 'msg_bg_%';
